BEGIN TRANSACTION;
CREATE TABLE "accounts_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "full_name" varchar(150) NOT NULL, "role" varchar(30) NOT NULL, "phone" varchar(20) NOT NULL, "assigned_district_id" bigint NULL REFERENCES "geography_district" ("id") DEFERRABLE INITIALLY DEFERRED, "assigned_facility_id" bigint NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "accounts_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "accounts_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "alerts_alert" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "alert_type" varchar(40) NOT NULL, "severity" varchar(20) NOT NULL, "title" varchar(200) NOT NULL, "description" text NOT NULL, "status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "assigned_user_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NULL REFERENCES "patients_patient" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "ars_arsactionitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "task_description" text NOT NULL, "responsible_person" varchar(150) NOT NULL, "due_date" date NOT NULL, "status" varchar(20) NOT NULL, "meeting_id" bigint NOT NULL REFERENCES "ars_arsmeeting" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "ars_arsmeeting" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "meeting_date" date NOT NULL, "chairperson_name" varchar(150) NOT NULL, "attendees_count" integer NOT NULL, "agenda" text NOT NULL, "proceedings_summary" text NOT NULL, "untied_funds_spent_rs" decimal NOT NULL, "signed_by_chairman" bool NOT NULL, "facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "ars_arsmember" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL, "designation" varchar(100) NOT NULL, "mobile" varchar(20) NOT NULL, "facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "audit_auditlog" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "username_snapshot" varchar(150) NOT NULL, "action" varchar(100) NOT NULL, "details" text NOT NULL, "ip_address" char(39) NULL, "timestamp" datetime NOT NULL, "facility_id" bigint NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "compliance_complianceitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "requirement_id" varchar(50) NOT NULL UNIQUE, "requirement_text" text NOT NULL, "source_document" varchar(100) NOT NULL, "classification" varchar(50) NOT NULL, "application_module" varchar(100) NOT NULL, "status" varchar(30) NOT NULL, "explanation" text NOT NULL);
CREATE TABLE "consultations_consultation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "chief_complaint" text NOT NULL, "clinical_history" text NOT NULL, "clinical_assessment" text NOT NULL, "diagnosis_code" varchar(50) NOT NULL, "diagnosis_name" varchar(200) NOT NULL, "treatment_plan" text NOT NULL, "follow_up_date" date NULL, "clinical_notes" text NOT NULL, "created_at" datetime NOT NULL, "doctor_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "patients_patient" ("id") DEFERRABLE INITIALLY DEFERRED, "visit_id" bigint NOT NULL UNIQUE REFERENCES "visits_visit" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "consultations_prescription" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date" date NOT NULL, "status" varchar(20) NOT NULL, "notes" text NOT NULL, "consultation_id" bigint NOT NULL UNIQUE REFERENCES "consultations_consultation" ("id") DEFERRABLE INITIALLY DEFERRED, "doctor_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "patients_patient" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "consultations_prescriptionitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "medicine_name" varchar(150) NOT NULL, "dosage" varchar(50) NOT NULL, "frequency" varchar(50) NOT NULL, "duration_days" integer NOT NULL, "quantity" integer NOT NULL, "status" varchar(20) NOT NULL, "prescription_id" bigint NOT NULL REFERENCES "consultations_prescription" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "facilities_facility" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "facility_code" varchar(50) NOT NULL UNIQUE, "facility_name" varchar(200) NOT NULL, "facility_type" varchar(30) NOT NULL, "city_or_ulb" varchar(100) NOT NULL, "urban_rural" varchar(10) NOT NULL, "address" text NOT NULL, "latitude" decimal NOT NULL, "longitude" decimal NOT NULL, "population_served" integer NOT NULL, "vulnerable_population" integer NOT NULL, "phone" varchar(20) NOT NULL, "email" varchar(254) NOT NULL, "opening_time" varchar(20) NOT NULL, "closing_time" varchar(20) NOT NULL, "emergency_available" bool NOT NULL, "lab_available" bool NOT NULL, "pharmacy_available" bool NOT NULL, "teleconsultation_available" bool NOT NULL, "bed_capacity" integer NOT NULL, "services" text NOT NULL, "specialists" text NOT NULL, "status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "district_id" bigint NOT NULL REFERENCES "geography_district" ("id") DEFERRABLE INITIALLY DEFERRED, "parent_facility_id" bigint NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED, "state_id" bigint NOT NULL REFERENCES "geography_state" ("id") DEFERRABLE INITIALLY DEFERRED, "ward_id" bigint NULL REFERENCES "geography_ward" ("id") DEFERRABLE INITIALLY DEFERRED, "zone_id" bigint NULL REFERENCES "geography_zone" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "facilities_facilityrelationship" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "relationship_type" varchar(30) NOT NULL, "service" varchar(100) NOT NULL, "priority" varchar(20) NOT NULL, "distance_km" decimal NOT NULL, "active" bool NOT NULL, "notes" text NOT NULL, "created_at" datetime NOT NULL, "destination_facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED, "source_facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "geography_district" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "code" varchar(20) NOT NULL UNIQUE, "state_id" bigint NOT NULL REFERENCES "geography_state" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "geography_state" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL UNIQUE, "code" varchar(10) NOT NULL UNIQUE);
CREATE TABLE "geography_ward" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "ward_number" integer NOT NULL, "name" varchar(100) NOT NULL, "population" integer NOT NULL, "slum_population" integer NOT NULL, "zone_id" bigint NOT NULL REFERENCES "geography_zone" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "geography_zone" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "code" varchar(20) NOT NULL, "district_id" bigint NOT NULL REFERENCES "geography_district" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "integrations_integrationconfiguration" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "system_name" varchar(50) NOT NULL UNIQUE, "display_name" varchar(150) NOT NULL, "status" varchar(20) NOT NULL, "last_sync_time" datetime NULL, "sync_status" varchar(30) NOT NULL, "notes" text NOT NULL);
CREATE TABLE "laboratory_laborder" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "order_date" datetime NOT NULL, "status" varchar(30) NOT NULL, "consultation_id" bigint NULL REFERENCES "consultations_consultation" ("id") DEFERRABLE INITIALLY DEFERRED, "doctor_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "patients_patient" ("id") DEFERRABLE INITIALLY DEFERRED, "test_master_id" bigint NOT NULL REFERENCES "laboratory_labtestmaster" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "laboratory_labresult" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "result_value" varchar(100) NOT NULL, "unit" varchar(20) NOT NULL, "reference_range" varchar(100) NOT NULL, "interpretation_flag" varchar(20) NOT NULL, "verified_at" datetime NOT NULL, "notes" text NOT NULL, "lab_order_id" bigint NOT NULL UNIQUE REFERENCES "laboratory_laborder" ("id") DEFERRABLE INITIALLY DEFERRED, "verified_by_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "laboratory_labsample" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "sample_type" varchar(50) NOT NULL, "sample_code" varchar(50) NOT NULL UNIQUE, "collected_at" datetime NOT NULL, "collected_by_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "lab_order_id" bigint NOT NULL UNIQUE REFERENCES "laboratory_laborder" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "laboratory_labtestmaster" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(50) NOT NULL UNIQUE, "name" varchar(150) NOT NULL, "category" varchar(50) NOT NULL, "reference_range" varchar(100) NOT NULL, "unit" varchar(20) NOT NULL);
CREATE TABLE "ncd_ncdrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "screening_date" date NOT NULL, "hypertension_screened" bool NOT NULL, "hypertension_diagnosed" bool NOT NULL, "diabetes_screened" bool NOT NULL, "diabetes_diagnosed" bool NOT NULL, "risk_level" varchar(20) NOT NULL, "treatment_status" varchar(30) NOT NULL, "control_status" varchar(30) NOT NULL, "last_bp" varchar(20) NOT NULL, "last_glucose" integer NOT NULL, "next_followup_due" date NULL, "facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "patients_patient" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "outreach_outreachactivity" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "activity_type" varchar(100) NOT NULL, "activity_date" date NOT NULL, "households_covered" integer NOT NULL, "persons_screened" integer NOT NULL, "vulnerable_identified" integer NOT NULL, "conducted_by" varchar(150) NOT NULL, "summary_notes" text NOT NULL, "facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED, "ward_id" bigint NULL REFERENCES "geography_ward" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "patients_household" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "household_id" varchar(50) NOT NULL UNIQUE, "head_name" varchar(150) NOT NULL, "address" text NOT NULL, "members_count" integer NOT NULL, "vulnerable_category" varchar(100) NOT NULL, "created_at" date NOT NULL, "ward_id" bigint NULL REFERENCES "geography_ward" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "patients_patient" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "patient_id" varchar(50) NOT NULL UNIQUE, "name" varchar(150) NOT NULL, "date_of_birth" date NULL, "age" integer NOT NULL, "gender" varchar(10) NOT NULL, "mobile" varchar(20) NOT NULL, "address" text NOT NULL, "ABHA_ID_DEMO" varchar(50) NOT NULL, "emergency_contact" varchar(100) NOT NULL, "vulnerability_information" varchar(100) NOT NULL, "registration_date" date NOT NULL, "district_id" bigint NULL REFERENCES "geography_district" ("id") DEFERRABLE INITIALLY DEFERRED, "registered_at_facility_id" bigint NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED, "ward_id" bigint NULL REFERENCES "geography_ward" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "pharmacy_inventorytransaction" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "transaction_type" varchar(30) NOT NULL, "quantity" integer NOT NULL, "reference_id" varchar(100) NOT NULL, "created_at" datetime NOT NULL, "created_by_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED, "batch_id" bigint NULL REFERENCES "pharmacy_medicinebatch" ("id") DEFERRABLE INITIALLY DEFERRED, "medicine_id" bigint NOT NULL REFERENCES "pharmacy_medicinemaster" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "pharmacy_medicinebatch" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "batch_number" varchar(50) NOT NULL, "supplier" varchar(100) NOT NULL, "received_date" date NOT NULL, "expiry_date" date NOT NULL, "quantity" integer NOT NULL, "unit_cost" decimal NOT NULL, "status" varchar(20) NOT NULL, "facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED, "medicine_id" bigint NOT NULL REFERENCES "pharmacy_medicinemaster" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "pharmacy_medicinemaster" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "generic_name" varchar(150) NOT NULL, "brand_name" varchar(150) NOT NULL, "strength" varchar(50) NOT NULL, "dosage_form" varchar(50) NOT NULL, "unit" varchar(20) NOT NULL, "category" varchar(50) NOT NULL, "reorder_level" integer NOT NULL);
CREATE TABLE "quality_biomedicalwastelog" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date" date NOT NULL, "yellow_bag_kg" decimal NOT NULL, "red_bag_kg" decimal NOT NULL, "white_translucent_sharp_kg" decimal NOT NULL, "blue_box_glass_kg" decimal NOT NULL, "disposal_agency" varchar(150) NOT NULL, "facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED, "handed_over_by_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "quality_qualitychecklist" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "inspection_date" date NOT NULL, "cleanliness_score" integer NOT NULL, "infection_control_passed" bool NOT NULL, "kayakalpa_audit_status" varchar(50) NOT NULL, "corrective_actions" text NOT NULL, "facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED, "inspected_by_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "referrals_followup" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "category" varchar(30) NOT NULL, "due_date" date NOT NULL, "status" varchar(20) NOT NULL, "notes" text NOT NULL, "facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "patients_patient" ("id") DEFERRABLE INITIALLY DEFERRED, "visit_id" bigint NULL REFERENCES "visits_visit" ("id") DEFERRABLE INITIALLY DEFERRED, "referral_id" bigint NULL REFERENCES "referrals_referral" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "referrals_referral" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "referral_id" varchar(50) NOT NULL UNIQUE, "reason" text NOT NULL, "clinical_summary" text NOT NULL, "required_service" varchar(100) NOT NULL, "urgency" varchar(20) NOT NULL, "referral_date" datetime NOT NULL, "status" varchar(30) NOT NULL, "destination_facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "patients_patient" ("id") DEFERRABLE INITIALLY DEFERRED, "referring_doctor_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "source_facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "referrals_referralresponse" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "specialist_findings" text NOT NULL, "treatment_summary" text NOT NULL, "return_advice" text NOT NULL, "responded_at" datetime NOT NULL, "hospital_doctor_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "referral_id" bigint NOT NULL UNIQUE REFERENCES "referrals_referral" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "surveillance_diseasecase" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "disease_name" varchar(100) NOT NULL, "report_date" date NOT NULL, "severity" varchar(20) NOT NULL, "status" varchar(20) NOT NULL, "notes" text NOT NULL, "facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "patients_patient" ("id") DEFERRABLE INITIALLY DEFERRED, "ward_id" bigint NULL REFERENCES "geography_ward" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "telemedicine_teleconsultation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "teleconsult_id" varchar(50) NOT NULL UNIQUE, "specialty_required" varchar(100) NOT NULL, "scheduled_time" datetime NOT NULL, "status" varchar(20) NOT NULL, "clinical_notes" text NOT NULL, "specialist_advice" text NOT NULL, "created_at" datetime NOT NULL, "clinic_facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED, "hub_facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "patients_patient" ("id") DEFERRABLE INITIALLY DEFERRED, "requesting_doctor_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "specialist_doctor_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "triage_triagevitals" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "blood_pressure_systolic" integer NOT NULL, "blood_pressure_diastolic" integer NOT NULL, "pulse_bpm" integer NOT NULL, "temperature_f" decimal NOT NULL, "spo2_percent" integer NOT NULL, "respiratory_rate" integer NOT NULL, "height_cm" decimal NOT NULL, "weight_kg" decimal NOT NULL, "bmi" decimal NOT NULL, "blood_glucose_mgdl" integer NOT NULL, "high_bp_flag" bool NOT NULL, "high_glucose_flag" bool NOT NULL, "fever_flag" bool NOT NULL, "low_spo2_flag" bool NOT NULL, "pregnancy_high_risk_flag" bool NOT NULL, "emergency_flag" bool NOT NULL, "ncd_risk_flag" bool NOT NULL, "nurse_notes" text NOT NULL, "created_at" datetime NOT NULL, "nurse_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "patients_patient" ("id") DEFERRABLE INITIALLY DEFERRED, "visit_id" bigint NOT NULL UNIQUE REFERENCES "visits_visit" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "visits_token" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "token_number" integer NOT NULL, "date" date NOT NULL, "priority" varchar(20) NOT NULL, "status" varchar(20) NOT NULL, "facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED, "visit_id" bigint NOT NULL UNIQUE REFERENCES "visits_visit" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "visits_visit" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "visit_id" varchar(50) NOT NULL UNIQUE, "visit_date" datetime NOT NULL, "visit_type" varchar(40) NOT NULL, "status" varchar(30) NOT NULL, "chief_complaint" text NOT NULL, "assigned_doctor_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "patients_patient" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "wellness_wellnesssession" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "session_type" varchar(50) NOT NULL, "instructor_name" varchar(150) NOT NULL, "session_date" date NOT NULL, "session_time" varchar(30) NOT NULL, "venue" varchar(150) NOT NULL, "participants_count" integer NOT NULL, "incentive_amount_rs" decimal NOT NULL, "notes" text NOT NULL, "facility_id" bigint NOT NULL REFERENCES "facilities_facility" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX "geography_district_state_id_37a7f3af" ON "geography_district" ("state_id");
CREATE INDEX "geography_zone_district_id_42e7146e" ON "geography_zone" ("district_id");
CREATE INDEX "geography_ward_zone_id_396ecac3" ON "geography_ward" ("zone_id");
CREATE INDEX "facilities_facility_district_id_6e35953c" ON "facilities_facility" ("district_id");
CREATE INDEX "facilities_facility_parent_facility_id_7856792e" ON "facilities_facility" ("parent_facility_id");
CREATE INDEX "facilities_facility_state_id_6446c57b" ON "facilities_facility" ("state_id");
CREATE INDEX "facilities_facility_ward_id_a6bd79f1" ON "facilities_facility" ("ward_id");
CREATE INDEX "facilities_facility_zone_id_3d093ccf" ON "facilities_facility" ("zone_id");
CREATE INDEX "facilities_facilityrelationship_destination_facility_id_5674a24a" ON "facilities_facilityrelationship" ("destination_facility_id");
CREATE INDEX "facilities_facilityrelationship_source_facility_id_11b1c441" ON "facilities_facilityrelationship" ("source_facility_id");
CREATE UNIQUE INDEX "django_content_type_app_label_model_76bd3d3b_uniq" ON "django_content_type" ("app_label", "model");
CREATE UNIQUE INDEX "auth_group_permissions_group_id_permission_id_0cd325b0_uniq" ON "auth_group_permissions" ("group_id", "permission_id");
CREATE INDEX "auth_group_permissions_group_id_b120cbf9" ON "auth_group_permissions" ("group_id");
CREATE INDEX "auth_group_permissions_permission_id_84c5c92e" ON "auth_group_permissions" ("permission_id");
CREATE UNIQUE INDEX "auth_permission_content_type_id_codename_01ab375a_uniq" ON "auth_permission" ("content_type_id", "codename");
CREATE INDEX "auth_permission_content_type_id_2f476e4b" ON "auth_permission" ("content_type_id");
CREATE INDEX "accounts_user_assigned_district_id_7173d217" ON "accounts_user" ("assigned_district_id");
CREATE INDEX "accounts_user_assigned_facility_id_7a453a02" ON "accounts_user" ("assigned_facility_id");
CREATE UNIQUE INDEX "accounts_user_groups_user_id_group_id_59c0b32f_uniq" ON "accounts_user_groups" ("user_id", "group_id");
CREATE INDEX "accounts_user_groups_user_id_52b62117" ON "accounts_user_groups" ("user_id");
